draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // elephant body
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // elephant head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // elephant ears
  ctx.beginPath();
  ctx.arc(W/2 - 40, H/2 - 90, 20, 0, Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 40, H/2 - 90, 20, 0, Math.PI);
  ctx.fill();
  ctx.stroke();

  // elephant tusk
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 40);
  ctx.lineTo(W/2 - 30, H/2 - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 - 40);
  ctx.lineTo(W/2 + 30, H/2 - 70);
  ctx.stroke();

  // mourning expression
  ctx.beginPath();
  ctx.arc(W/2 - 15, H/2 - 100, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 15, H/2 - 100, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 110);
  ctx.lineTo(W/2 + 20, H/2 - 110);
  ctx.stroke();

  // lost herd in background
  ctx.fillStyle = 'gray';
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 150, H/2 - 30, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 200, H/2 + 30, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.globalAlpha = 1;

  // movement
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.translate(-W/2, -H/2);

  ctx.restore();
}
